@extends('layouts.admin') @section('title',$report->report_number) @section('content') @php($prefix=request()->routeIs('superadmin.*')?'superadmin':'admin')<a href="{{ route($prefix.'.reports.index') }}" class="text-sm text-brand-600">← Reports</a><div class="mt-2 flex flex-wrap justify-between gap-3"><div><h1 class="text-2xl font-extrabold">{{ $report->report_number }}</h1><p class="text-sm text-slate-500">{{ ucwords(str_replace('_',' ',$report->reason)) }} · {{ ucwords(str_replace('_',' ',$report->source)) }}</p></div><x-admin.status-badge :status="$report->status"/></div><div class="mt-6 grid gap-6 lg:grid-cols-3"><div class="space-y-6 lg:col-span-2"><div class="card p-5"><h2 class="font-bold">Report Details</h2><dl class="mt-4 grid gap-4 sm:grid-cols-2"><div><dt class="text-xs text-slate-400">Reporter</dt><dd>{{ $report->reporter?->name ?? 'Automated System' }}</dd></div><div><dt class="text-xs text-slate-400">Target</dt><dd>{{ class_basename($report->target_type) }} #{{ $report->target_id }}</dd></div><div class="sm:col-span-2"><dt class="text-xs text-slate-400">Description</dt><dd>{{ $report->description ?: 'No description.' }}</dd></div></dl>@if($report->evidence->isNotEmpty())<div class="mt-4 flex gap-3">@foreach($report->evidence as $item)<img src="{{ asset('storage/'.$item->path) }}" class="h-24 w-24 rounded-lg object-cover">@endforeach</div>@endif</div><div class="card p-5"><h2 class="font-bold">History & Notes</h2>@foreach($report->actions as $item)<div class="border-t py-3 text-sm"><b>{{ ucwords(str_replace('_',' ',$item->action)) }}</b> · {{ $item->user?->name ?? 'System' }}<p class="text-slate-500">{{ $item->reason }} · {{ $item->created_at->format('M d, Y g:i A') }}</p></div>@endforeach @foreach($report->notes as $note)<div class="border-t py-3 text-sm"><b>{{ $note->user->name }}</b><p>{{ $note->note }}</p></div>@endforeach</div><div class="card p-5"><h2 class="font-bold">Previous Confirmed Violations</h2>@forelse($violations as $v)<div class="border-t py-3"><b>{{ ucwords(str_replace('_',' ',$v->category)) }}</b><p class="text-sm text-slate-500">{{ $v->action_taken }} · {{ $v->created_at->format('M d, Y') }}</p></div>@empty<p class="mt-4 text-sm text-slate-500">No confirmed violations.</p>@endforelse</div></div><aside class="space-y-6"><form method="POST" action="{{ route($prefix.'.reports.update',$report) }}" class="card space-y-4 p-5">@csrf @method('PUT')<h2 class="font-bold">Review Report</h2><select class="input" name="status">@foreach(['open','under_review','resolved','dismissed','escalated'] as $s)<option value="{{ $s }}" @selected($report->status===$s)>{{ ucwords(str_replace('_',' ',$s)) }}</option>@endforeach</select><select class="input" name="assigned_to"><option value="">Unassigned</option>@foreach($admins as $admin)<option value="{{ $admin->id }}" @selected($report->assigned_to===$admin->id)>{{ $admin->name }}</option>@endforeach</select><textarea class="input" name="note" placeholder="Internal note"></textarea><button class="btn-primary w-full">Save Review</button></form>@if(auth()->user()->isSuperAdmin())<form method="POST" action="{{ route('superadmin.reports.enforce',$report) }}" class="card space-y-4 p-5">@csrf<h2 class="font-bold">Enforcement</h2><select class="input" name="action">@foreach(['warn_seller','hide_product','suspend_product','restore_product','restrict_shop','suspend_shop','reactivate_shop'] as $a)<option value="{{ $a }}">{{ ucwords(str_replace('_',' ',$a)) }}</option>@endforeach</select><textarea class="input" name="reason" required placeholder="Required reason"></textarea><button class="btn-primary w-full">Apply Action</button></form>@endif</aside></div>@endsection
